import{_ as i,l as m,o as e,c as E,v as t,p as o,x as r,d as l,i as n,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Deflated Sharpe","description":"","frontmatter":{"title":"Deflated Sharpe","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/deflated-sharpe.md","filePath":"quant/deflated-sharpe.md","lastUpdated":1789023840000}'),S={name:"quant/deflated-sharpe.md"};function p(s,a,A,R,B,D){const h=m("Mermaid");return e(),E("div",null,[a[1]||(a[1]=t('<h1 id="deflated-sharpe" tabindex="-1">Deflated Sharpe <a class="header-anchor" href="#deflated-sharpe" aria-label="Permalink to &quot;Deflated Sharpe&quot;">​</a></h1><div class="epigraph"><p>在足够多次试验之后，即使真实技能为零，样本内最大夏普也会高到看起来像发现；需要把选择偏差、非正态与试验次数写进同一张夏普的统计量里。</p><footer>—— Bailey and López de Prado, The Deflated Sharpe Ratio, Journal of Portfolio Management, 2014</footer></div><p><a href="/quant/cv-leakage-finance">上一课</a>把金融交叉验证的泄漏钉住：随机打乱、\\(K\\) 折共享未来路径、预处理在全样本上拟合，都会把评估器弄偏。缺口是评估器无偏之后，你报告的往往不是预先指定的那一个夏普，而是 \\(N\\) 次试验里最大的那个。本课写 Deflated Sharpe：对<strong>被选择过的夏普</strong>做假设检验。不重讲 purge/embargo。后课 CPCV 默认已经读完：DSR 回答「这个点估计还剩多少技能」，不替代多条样本外路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设策略超额收益的样本夏普为 \\(\\widehat{\\mathrm{SR}}\\)。若收益独立正态，对 \\(\\mathrm{SR}=0\\) 的检验大约看 \\(\\widehat{\\mathrm{SR}}\\sqrt{T}\\)。真实收益有偏度 \\(\\gamma_3\\)、超额峰度 \\(\\gamma_4\\)，Mertens 给出 \\(\\widehat{\\mathrm{SR}}\\) 的渐近方差还含 \\(1-\\gamma_3\\mathrm{SR}+(\\gamma_4-1)\\mathrm{SR}^2/4\\) 一项。左偏、肥尾时，同样的点估计更不可信。Lo 的结论是：不要把夏普当无量纲的确定性标签，它是有抽样误差的估计量。</p><p>选择偏差把问题从「这一个估计量」变成「最大值的估计量」。\\(N\\) 个互不相关的零技能策略，最大样本夏普大约按极值分布随 \\(\\sqrt{\\log N}\\) 上升。Bailey、Borwein、López de Prado 与 Zhu（2014）在 AMS 通告里把这种现象称为回测过拟合：试验次数足够大时，漂亮回测几乎必然出现。Harvey、Liu 与 Zhu（2016）在因子发现上得到平行结论——\\(t=2\\) 不够。DSR 的对象是交易策略的夏普，机制与多重检验相同：未申报的尝试次数是暗数，任何「显著夏普」都必须相对这个暗数来读。</p><h3 id="概率夏普与被放气的阈值" tabindex="-1">概率夏普与被放气的阈值 <a class="header-anchor" href="#概率夏普与被放气的阈值" aria-label="Permalink to &quot;概率夏普与被放气的阈值&quot;">​</a></h3><p>Bailey–López de Prado 先定义概率夏普（PSR）：在估计了偏度与峰度之后，\\(\\widehat{\\mathrm{SR}}\\) 超过某个阈值 \\(\\mathrm{SR}^*\\) 的概率（用正态 CDF 作渐近近似）。普通 PSR 仍假设你只试验了一次，\\(\\mathrm{SR}^*\\) 可以取 0 或取融资与风险厌恶要求的最低夏普。DSR 把 \\(\\mathrm{SR}^*\\) 换成<strong>零技能下、\\(N\\) 次试验最大夏普的期望</strong>。观测夏普必须先超过这场选美的预期冠军，剩下来的部分才拿去对非正态做标准化。于是「放气」有两层：一层对分布形状，一层对多重试验。</p><p><span class="marginnote">\\(N\\) 不是参数网格的格子数那么简单。换品种、换起止日期、换成本假设、换仓位规则、看过结果再改信号，都算试验。Git 与实验跟踪里的运行次数，往往比论文脚注里的 \\(N\\) 更接近真相。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记 \\(\\hat\\gamma_3,\\hat\\gamma_4\\) 为样本偏度与峰度，\\(T\\) 为观测数。在阈值 \\(\\mathrm{SR}_0\\) 处，</p> \\[\\widehat{\\mathrm{DSR}}=Z\\left[\\frac{(\\widehat{\\mathrm{SR}}-\\mathrm{SR}_0)\\sqrt{T-1}}{\\sqrt{1-\\hat\\gamma_3\\widehat{\\mathrm{SR}}+\\frac{\\hat\\gamma_4-1}{4}\\widehat{\\mathrm{SR}}^2}}\\right], \\]<p>其中 \\(Z\\) 为标准正态 CDF。\\(\\mathrm{SR}_0\\) 取零技能下最大夏普的期望。对 \\(N\\) 次试验、试验间夏普的方差 \\(V[\\{\\widehat{\\mathrm{SR}}_n\\}]\\)，Bailey–López de Prado 用极值近似：</p> \\[\\mathrm{SR}_0=\\sqrt{V[\\{\\widehat{\\mathrm{SR}}_n\\}]}\\left((1-\\gamma)Z^{-1}\\left(1-\\tfrac{1}{N}\\right)+\\gamma Z^{-1}\\left(1-\\tfrac{1}{Ne}\\right)\\right), \\]<p>\\(\\gamma\\) 为欧拉常数。直观地说：\\(N\\) 越大、试验间夏普越分散，\\(\\mathrm{SR}_0\\) 越高，同样的 \\(\\widehat{\\mathrm{SR}}\\) 对应的 DSR 越低。若只有一次预注册试验，\\(N=1\\)，\\(\\mathrm{SR}_0\\) 退回你指定的最低可接受夏普，DSR 接近 PSR。</p><h3 id="如何估计-与" tabindex="-1">如何估计 \\(N\\) 与 \\(V\\) <a class="header-anchor" href="#如何估计-与" aria-label="Permalink to &quot;如何估计 $N$ 与 $V$&quot;">​</a></h3><p>\\(N\\) 应取实际上发生过的独立试验的有效个数。完全相关的两次网格点不应算两次；几乎独立的信号家族应分开累加。\\(V[\\{\\widehat{\\mathrm{SR}}_n\\}]\\) 可用同一簇回测的夏普样本方差估计；若只有最终那一个夏普，就只能给 \\(V\\) 一个保守假设（例如非技能策略夏普的经验离散度）。Harvey 与 Liu（2015）讨论回测中的多重检验时给出类似精神：与其假装 \\(N=1\\)，不如给 \\(N\\) 一个有依据的下限，报告 DSR 对 \\(N\\) 的敏感性。把 DSR 做成一张表：横轴 \\(N\\)，纵轴 DSR，比单独报一个 0.95 更难被操纵。</p><p><span class="marginnote">DSR 高并不授权加大杠杆。它只是说：在你承认的试验次数与非正态下，夏普不像是纯选择偏差。仓位仍受<a href="/quant/net-edge">扣费后边缘</a>、<a href="/quant/capacity-participation">容量</a> 与估计误差约束；满 Kelly 加上被选择过的夏普是常见的破产路径。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>选择偏差抬高的是 \\(\\mathbb{E}[\\max_n\\widehat{\\mathrm{SR}}_n]\\)，不抬高任何单个策略的真实 \\(\\mathrm{SR}\\)。DSR 把检验的原假设从「这个夏普来自零技能的一次抽样」改成「这个夏普来自零技能的 \\(N\\) 次抽样的最大值」。拒绝后者严格更难，这正是目的。非正态项则防止你用正态临界值去读一个左偏策略：同样的点估计，负偏会降低 DSR，因为均值对少数亏损更敏感、夏普的抽样方差更大。</p><p>与 White 的 Reality Check、Hansen 的 SPA 相比，DSR 是对<strong>已经选出的那一个</strong>夏普做修正的解析近似，而不是对整簇策略的最大统计量做自举。优点是只要 \\(T\\)、\\(N\\)、矩和夏普即可计算，适合写进每一张回测表的脚注；缺点是极值近似依赖试验近似独立、以及夏普近似正态——策略高度相关时有效 \\(N\\) 更小，直接代入名义 \\(N\\) 会过罚；试验结构复杂时，<a href="/quant/cpcv">CPCV</a> 的路径分布更忠实。</p><h3 id="与因子研究的-门槛" tabindex="-1">与因子研究的 \\(t\\gt 3\\) 门槛 <a class="header-anchor" href="#与因子研究的-门槛" aria-label="Permalink to &quot;与因子研究的 $t\\gt 3$ 门槛&quot;">​</a></h3><p>Harvey–Liu–Zhu 的 \\(t\\approx 3\\) 是对因子动物园规模的校准；DSR 是对单个策略回测的校准。两者不要互相替代。因子论文应报多重检验后的 \\(t\\) 或 FDR；交易系统应报 PSR/DSR，并声明 \\(N\\)。一个 DSR 很高的日内反转，仍可能在 HLZ 意义上只是被翻遍的异常表里的幸运者——若它来自同一张异常表，两种调整都要做。发表后衰减（McLean–Pontiff）提供第三种证据：统计量过关之后，仍要用未参与选择的样本看夏普是否还在。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>DSR 对 \\(N\\) 的误报极度敏感。故意把 \\(N\\) 说小，是最廉价的「显著」。相反，把所有历史实验、包括不相关市场的失败都算进 \\(N\\)，会过罚一个预注册策略。纪律是：预先定义搜索空间，按空间的有效维度计 \\(N\\)，搜索空间外的灵感要么预注册新的一次试验，要么承认 \\(N\\) 增加。非正态修正是渐近的，\\(T\\) 很小时正态 CDF 本身不可靠，应改用自举或更长样本。</p><p>不要用 DSR 替代成本与容量。把成本设为零会抬高 \\(\\widehat{\\mathrm{SR}}\\)，DSR 只是把这个被抬高的数字放气；放气后仍显著，只说明「零成本世界里的选择偏差不足以解释它」，不说明扣费后可交易。也不要把样本外拼接曲线的夏普再送进 DSR 却把 \\(N\\) 设为 1——若样本外被用来在模型和窗口之间选择，见<a href="/quant/walk-forward">滚动检验</a>，\\(N\\) 仍然大于 1。</p><p><span class="marginnote">夏普对波动估计敏感。用已实现波动的某一变换、或去掉某个回撤年再算夏普，都是额外试验。DSR 公式里的 \\(\\widehat{\\mathrm{SR}}\\) 必须与声明的收益定义一致，包括融资、分红与费用。</span></p>',27)),(e(),o(d,null,{default:r(()=>[n(h,{id:"mermaid-75",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22N%20%E6%AC%A1%E5%9B%9E%E6%B5%8B%E5%BE%97%E5%88%B0%E4%B8%80%E7%B0%87%E5%A4%8F%E6%99%AE%22%5D%20--%3E%20MAX%5B%22%E9%80%89%E5%87%BA%E6%8A%A5%E5%91%8A%E7%94%A8%E7%9A%84%20SR_hat%22%5D%0A%20%20MOM%5B%22%E5%81%8F%E5%BA%A6%E4%B8%8E%E5%B3%B0%E5%BA%A6%22%5D%20--%3E%20PSR%5B%22PSR%EF%BC%9A%E9%9D%9E%E6%AD%A3%E6%80%81%E4%B8%8B%E8%B6%85%E8%BF%87%E9%98%88%E5%80%BC%E7%9A%84%E6%A6%82%E7%8E%87%22%5D%0A%20%20MAX%20--%3E%20PSR%0A%20%20TR%20--%3E%20V%5B%22%E8%AF%95%E9%AA%8C%E9%97%B4%E5%A4%8F%E6%99%AE%E7%9A%84%E7%A6%BB%E6%95%A3%E5%BA%A6%22%5D%0A%20%20N%5B%22%E6%9C%89%E6%95%88%E8%AF%95%E9%AA%8C%E6%AC%A1%E6%95%B0%20N%22%5D%20--%3E%20SR0%5B%22%E9%9B%B6%E6%8A%80%E8%83%BD%E4%B8%8B%E6%9C%80%E5%A4%A7%E5%A4%8F%E6%99%AE%E6%9C%9F%E6%9C%9B%20SR_0%22%5D%0A%20%20V%20--%3E%20SR0%0A%20%20SR0%20--%3E%20DSR%5B%22DSR%20%3D%20PSR(%E9%98%88%E5%80%BC%20%3D%20SR_0)%22%5D%0A%20%20PSR%20--%3E%20DSR%0A%20%20DSR%20--%3E%20DEC%7B%22DSR%20%E6%98%AF%E5%90%A6%E4%BB%8D%E9%AB%98%3F%22%7D%0A%20%20DEC%20--%3E%7C%E5%90%A6%7C%20REJ%5B%22%E8%A7%86%E4%B8%BA%E9%80%89%E6%8B%A9%E5%81%8F%E5%B7%AE%E6%88%96%E5%99%AA%E5%A3%B0%22%5D%0A%20%20DEC%20--%3E%7C%E6%98%AF%7C%20NEXT%5B%22%E5%86%8D%E8%BF%87%E6%88%90%E6%9C%AC%E3%80%81%E5%AE%B9%E9%87%8F%E4%B8%8E%E7%9C%9F%E6%AD%A3%E6%A0%B7%E6%9C%AC%E5%A4%96%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Deflated Sharpe 把非正态下夏普的抽样误差，与 \\(N\\) 次试验中最大值的选择偏差，合成一个概率陈述。</li><li>Lo（2002）说明夏普不是无误差的标签；Bailey–López de Prado（2014）说明被选择过的夏普必须相对极值阈值来读。</li><li>\\(N\\) 与试验间离散度是一等输入，应做敏感性表，而不是藏在「我们只试了几个参数」的句子里。</li><li>DSR 通过不等于可交易；成本和未参与选择的样本外仍是关卡。</li><li>与 Reality Check、SPA、CPCV 互补：DSR 便宜且可进每一张表，复杂相关结构时用路径方法。</li><li>出处：Bailey and López de Prado, <em>Journal of Portfolio Management</em>, 2014；Lo, <em>Financial Analysts Journal</em>, 2002；Bailey, Borwein, López de Prado and Zhu, <em>Notices of the AMS</em>, 2014；Harvey, Liu and Zhu, <em>RFS</em>, 2016；Harvey and Liu, <em>Journal of Portfolio Management</em>, 2015。</li></ul>',2))])}const c=i(S,[["render",p]]);export{_ as __pageData,c as default};
